def compute(vars):
    non_us_dollar_denominated = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    percentage = (non_us_dollar_denominated / total) * 100
    return {
        "value": percentage,
        "trace": {
            "non_us_dollar_denominated": non_us_dollar_denominated,
            "total": total,
            "ratio": non_us_dollar_denominated / total,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
